import React, { useEffect } from 'react'
import styled from 'styled-components'
import { theme } from 'theme'
import { Form, message, Modal, Tooltip } from 'antd'
import FlowLayout from 'components/features/onboard/FlowLayout'
import TextInput from 'components/features/onboard/TextInput'
import FlowNavButtons from 'components/features/onboard/FlowNavButtons'
import { nameRegex } from 'components/features/onboard/FlowScreens/Source';
import {
	InfoBox,
} from 'components/features/onboard/SignupSecondaryLayout';
import { FlowWrapper, SectionHeader } from 'components/features/onboard/FlowScreens/common'
import { showIntercom } from 'Utils/constants';
import { useDispatch, useSelector } from 'react-redux';
import { IReduxState } from 'types/reduxStateTypes';
import { createApplication, getAppDropdown } from 'redux/actions/appdropdown';
import { trackPageViews } from 'redux/actions/trackingReport';
import { getUser } from 'redux/actions/profile';
import { useRouter } from 'next/router';
import { changeCommonValue } from 'redux/actions/common';
import { focusInput } from 'components/features/onboard/FlowScreens/OrganizationApps';


const FormWrapper = styled.div`
	display: flex;
	flex-direction: column;
`

