const Checkbox = styled.input`
	display: none;
`

const InfoBoxWrapper = styled.div`
	margin-bottom: 24px;
`

interface FormData {
	appName: string;
	appType: string;
	region: string;
	mobileApps: boolean;
	webApps: boolean;
	us: boolean;
	eu: boolean;
	ae: boolean;
}

const CreateAppByWelcomeMessage = ({resetStatus}: {resetStatus: () => void}) => {
	const {
		currentOrgReducer: { planFeature },
		applicationReducer,
		profileReducer,
	} = useSelector((state: IReduxState) => state);
	const currentApp = applicationReducer?.[0]
	const { orgId, subscription } = currentApp || {}
	const { name: currentPlan } = subscription || {}

	const [form] = Form.useForm<FormData>()
	const dispatch = useDispatch()
	const router = useRouter()
	const IS_UAE_REGION_DISABLED = true
	const [loading, setLoading] = React.useState(false)
	const [subscriptionError, setSubscriptionError] = React.useState(false)
	const [platformsError, setPlatformsError] = React.useState<string | null>(null)
	const [regionError, setRegionError] = React.useState<string | null>(null)
	const mobileAppsValue = Form.useWatch('mobileApps', form)
	const webAppsValue = Form.useWatch('webApps', form)
	const usValue = Form.useWatch('us', form)
	const euValue = Form.useWatch('eu', form)
	const aeValue = Form.useWatch('ae', form)

	const regionSelectFeatureFlag = !!planFeature?.mriFeature
	const localData = React.useMemo(() => {
		try {
			const savedAppData = localStorage.getItem('signupApp') || '';
			return JSON.parse(savedAppData)
		} catch (error) {
			return null
			// Ignore invalid JSON in localStorage - silent fail
		}
	}, [])

	const handlePlatformChange = React.useCallback((platform: 'mobileApps' | 'webApps') => {
		return (checked: boolean) => {
			if (checked) {
				const { mobile, web } = localData || {}
				if (platform === 'mobileApps') {
					const nameValue = mobile?.length ? mobile : undefined
					form.setFieldsValue({ mobileApps: true, webApps: false, appName: nameValue })
				} else {
					const nameValue = web?.length ? web : undefined
					form.setFieldsValue({ mobileApps: false, webApps: true, appName: nameValue })
				}
			} else {
				form.setFieldsValue({ [platform]: false })
			}
		}
	}, [form, localData])

	const handleRegionChange = React.useCallback((region: 'us' | 'eu' | 'ae') => {
		return (checked: boolean) => {
			if (checked) {
				if (region === 'us') {
					form.setFieldsValue({ us: true, eu: false, ae: false })
				} else if (region === 'eu') {
					form.setFieldsValue({ us: false, eu: true, ae: false })
				}
                else {
					form.setFieldsValue({ us: false, eu: false, ae: true })
				}
			} else {
				form.setFieldsValue({ [region]: false })
			}
		}
	}, [form])

	useEffect(() => {
		if (localData) {
			const { mobile, web } = localData
			if ( (mobile?.length || web?.length) && !(mobile?.length && web?.length)) {

				form.setFieldsValue({
					mobileApps: !!mobile?.length,
					webApps: !!web?.length,
					appName: mobile?.length ? mobile : web,
				});
			}
		}
	}, [form, localData]);

	const eventSent = React.useRef(false);
	const [isComponentMounted, setIsComponentMounted] = React.useState(false);

	useEffect(() => {
		setIsComponentMounted(true);
	}, []);

	const eventData = React.useMemo(() => ({
		email: profileReducer?.email || '',
		orgName: currentApp?.name || '',
		orgId: orgId || '',
	}), [profileReducer?.email, currentApp?.name, orgId]);

	useEffect(() => {
		if (isComponentMounted && !eventSent.current && eventData.email && eventData.orgId) {
			dispatch(trackPageViews(null, {
				eventName: 'wa_screenvisit_setup_create_first_app',
				eventProperty: eventData
			}));
			eventSent.current = true;
		}
	}, [dispatch, isComponentMounted, eventData]);

	const handleAppCreation = React.useCallback(async (values: FormData) => {
		  setSubscriptionError(false)
		  setLoading(true)
		  let region;
		  if (values.us) {
              region = 'us';
          } else if (values.eu) {
              region = 'eu';
          } else {
              region = 'ae';
          }
		  const createPayload = {
			 orgId,
			 name: values.appName,
			 appType: values.mobileApps ? 'mobile' : 'web',
			 notifyEmail: false,
			 appCreatedFrom: 'signup',
			 region,
		  }

		  if (currentApp && typeof window !== 'undefined') {
			try {
				window.localStorage.setItem('orgId', orgId as string)
				if (currentPlan) {
				  window.localStorage.setItem('currentPlan', currentPlan)
				}
			} catch (err) {
				// silent fail
			}
		  }

		  try {
			 const res = await dispatch(createApplication(createPayload)) as any
			 if (!res.success) {
				setLoading(false)
				if (res?.error?.message?.includes('suspicious behavior')) {
				  dispatch(changeCommonValue('isVisible_custom_popup', true))
				} else if (res?.error?.message?.includes('Active subscription not found')) {
				  setSubscriptionError(true)
				  return
				} else if (res?.error) {
					if( res.error?.message ){
						message.error( res.error.message )
					} else if (res.error.name){
						message.error(res.error.name[0])
					}
				} else {
				  message.error('An unexpected error occurred. Please try again.')
				}
				return
			 }

			 dispatch(getAppDropdown())
			 resetStatus()
			 	try {
					window.localStorage.setItem('appId', res.data['_id'])
				} catch (err) {
					// silent fail
				}
			 setLoading(false)
			 dispatch(
				trackPageViews(null, {
				  eventName: 'sign_up',
				  track_type: 'event',
				  appId: res.data['_id'],
				})
			 )
			 dispatch(
				trackPageViews(null, {
				  eventName: 'wa_create_first_app',
				  eventProperty: {
					email: profileReducer?.email || '',
					appId: res.data['_id'],
					appName: values.appName,
					appType: values.mobileApps ? 'mobile' : 'web',
					region,
				  }

				})
			 )
			 dispatch(getUser())
			 localStorage.removeItem('signupApp');
			 router.push(
				`/integration?parentType=integration&appId=${res.data['_id']}`,
				`/integration?appId=${res.data['_id']}`
			 )
		  } catch (error: any) {
			 setLoading(false)
			 if (error && error.response) {
				if (
				  error.response.data.error.message &&
				  error.response.data.error.message.includes('suspicious behavior')
				) {
				  dispatch(changeCommonValue('isVisible_custom_popup', true))
				} else if (error.response.data.error.message?.includes('Active subscription not found')) {
				  setSubscriptionError(true)
			} else message.error(error.response.data.error.message)
			 } else {
				message.error('An unexpected error occurred. Please try again.')
			 }
		  }
		},
		[currentApp, currentPlan, dispatch, orgId, resetStatus, router, profileReducer?.email]
	)

	return (
		<FlowLayout
			title="Welcome! Let's set up your first app."
			subTitle="Start by creating your first app - you can add more apps later."
			progress={100}
			progressColor='green'
			hideLogos
		>
			<FlowWrapper>
				<Form
					form={form}
					onFinish={handleAppCreation}
					layout="vertical"
					autoComplete="off"
					validateTrigger={['onSubmit']}
				>
					<FormWrapper>
						<SectionHeader>
							Select your platform
						</SectionHeader>
						<PlaformOptionsContainer>
							<PlatformOptionButtons>
								<PlatformOptionButton>
									<Form.Item
										name="mobileApps"
										valuePropName='checked'
										initialValue={false}
										validateTrigger={['onSubmit']}
										rules={[{
											validator: () => {
												if (!mobileAppsValue && !webAppsValue) {
													setPlatformsError('Platform is required')
													return Promise.reject()
												}
												setPlatformsError(null)
												return Promise.resolve()
											}
										}]}
									>
										<Checkbox
											type="checkbox"
											disabled={loading}
											id="mobileApps"
											onChange={(e) => handlePlatformChange('mobileApps')(e.target.checked)}
										/>
									</Form.Item>
									<ButtonCheckbox
										htmlFor="mobileApps"
										tabIndex={0}
										aria-checked={mobileAppsValue}
										aria-disabled={loading}
									>
										<span>
											<img src="/static/mobile-app.svg" alt="Mobile App" />
											Mobile App
										</span>
									</ButtonCheckbox>
								</PlatformOptionButton>
								<PlatformOptionButton>
									<Form.Item
										name="webApps"
										valuePropName='checked'
										initialValue={false}
										validateTrigger={['onSubmit']}
										rules={[{
											validator: () => {
												if (!mobileAppsValue && !webAppsValue) {
													setPlatformsError('Platform is required')
													return Promise.reject()
												}
												setPlatformsError(null)
												return Promise.resolve()
											}
										}]}
									>
										<Checkbox
											type="checkbox"
											disabled={loading}
											id="webApps"
											onChange={(e) => handlePlatformChange('webApps')(e.target.checked)}
										/>
									</Form.Item>
									<ButtonCheckbox
										htmlFor="webApps"
										tabIndex={0}
										aria-checked={webAppsValue}
										aria-disabled={loading}
									>
										<span>
											<img src="/static/web-app.svg" alt="Web App" />
											Web App
										</span>
									</ButtonCheckbox>
								</PlatformOptionButton>
							</PlatformOptionButtons>
						{platformsError && (
							<div className="ant-form-item-explain-error">
								{platformsError}
							</div>
						)}
						</PlaformOptionsContainer>
						<SectionHeader>
							Enter app name
						</SectionHeader>
						<TextInput
							name="appName"
							ariaLabel='app name input'
							placeholder='Your app name'
							disabled={loading}
							rules={[
								{
									validator: (_, value) => {
										if (!value?.length) {
											focusInput('appName')
											return Promise.reject(new Error('App name is required'))
										}
										if (!nameRegex.test(value)) {
											focusInput('appName')
											return Promise.reject(new Error("Name field only accepts the following characters: alphabets (A-Z, a-z), numbers (0-9), dash (-), underscore (_), apostrophe ('), and spaces."))
										}
										if (value.length > 32) {
											focusInput('appName')
											return Promise.reject(new Error('App name should contain at most 32 characters.'))
										}
										return Promise.resolve()
									}
								}
							]}
						/>
						<SectionHeader>Select data storage region</SectionHeader>
						<PlaformOptionsContainer>
							<PlatformOptionButtons>
								<PlatformOptionButton>
									<Form.Item
										name="us"
										initialValue={false}
										valuePropName='checked'
										validateTrigger={['onSubmit']}
										rules={[{
											validator: () => {
												if (!usValue && !euValue && !aeValue) {
													setRegionError('Select a data storage region')
													return Promise.reject()
												}
												setRegionError(null)
												return Promise.resolve()
											}
										}]}
									>
										<Checkbox
											type="checkbox"
											disabled={loading}
											id="us"
											onChange={(e) => handleRegionChange('us')(e.target.checked)}
										/>
									</Form.Item>
									<ButtonCheckbox
										htmlFor="us"
										tabIndex={0}
										aria-checked={usValue}
										aria-disabled={loading}
									>
										<span>
											<img src="/static/signup/usflag.svg" alt="US" />
											US
										</span>
									</ButtonCheckbox>
								</PlatformOptionButton>
								<PlatformOptionButton>
									<Form.Item
										name="eu"
										valuePropName='checked'
										initialValue={false}
										validateTrigger={['onSubmit']}
										rules={[{
											validator: () => {
												if (!usValue && !euValue && !aeValue) {
													setRegionError('Data storage region is required')
													return Promise.reject()
												}
												setRegionError(null)
												return Promise.resolve()
											}
										}]}
									>
										<Checkbox
											type="checkbox"
											disabled={loading}
											id="eu"
											onChange={(e) => handleRegionChange('eu')(e.target.checked)}
										/>
									</Form.Item>
									<ButtonCheckbox
										htmlFor="eu"
										tabIndex={0}
										aria-checked={euValue}
										aria-disabled={loading}
									>
										<span>
											<img src="/static/signup/euflag.svg" alt="EU" />
											EU
										</span>
									</ButtonCheckbox>
								</PlatformOptionButton>
								<PlatformOptionButton>
									<Form.Item
										name="ae"
										valuePropName='checked'
										initialValue={false}
										validateTrigger={['onSubmit']}
										rules={[{
											validator: () => {
												if (!usValue && !euValue && !aeValue) {
													setRegionError('Data storage region is required')
													return Promise.reject()
												}
												setRegionError(null)
												return Promise.resolve()
											}
										}]}
									>
										<Checkbox
											type="checkbox"
											disabled={loading || IS_UAE_REGION_DISABLED}
											id="ae"
											onChange={(e) => handleRegionChange('ae')(e.target.checked)}
										/>
									</Form.Item>
									<Tooltip title={IS_UAE_REGION_DISABLED ? "UAE region is temporarily unavailable." : undefined}>
										<ButtonCheckbox
											htmlFor={IS_UAE_REGION_DISABLED ? undefined : "ae"}
											tabIndex={0}
											aria-checked={aeValue}
											aria-disabled={loading || IS_UAE_REGION_DISABLED}
											style={IS_UAE_REGION_DISABLED ? { opacity: 0.5, cursor: 'not-allowed' } : undefined}
										>
											<span>
												<img src="/static/signup/aeflag.svg" alt="UAE" />
												UAE
											</span>
										</ButtonCheckbox>
									</Tooltip>
								</PlatformOptionButton>
							</PlatformOptionButtons>
							{regionError && (
								<div className="ant-form-item-explain-error">
									{regionError}
								</div>
							)}
						</PlaformOptionsContainer>
						{ !regionSelectFeatureFlag && (usValue || euValue || aeValue) && (
							<InfoBoxWrapper>
								<InfoBox
									variant="gray"
									noMarginBottom
									text={
									<>
										The selected data storage location will apply to all future platforms. For multi-region storage, contact
										<InlineButton onClick={() => showIntercom()} type="button">
											support.
										</InlineButton>
									</>
									}
								/>
							</InfoBoxWrapper>
						)}
					</FormWrapper>
					<Modal
						visible={subscriptionError}
						onCancel={() => setSubscriptionError(false)}
						footer={null}
						centered
						destroyOnClose
						wrapClassName="subscription-error-modal"
					>
						<div style={{ textAlign: 'center', padding: '16px 0' }}>
							<h2 style={{ fontSize: 18, marginBottom: 16, color: '#161e35' }}>
								Active subscription not found for this organization.
							</h2>
							<p style={{ fontSize: 14, color: theme.colors.surface400?.toString() }}>
								<InlineButton
									onClick={() => { showIntercom(); setSubscriptionError(false); }}
									type="button"
									style={{ fontSize: 14, padding: '0 2px 0 0' }}
								>
									Talk to us
								</InlineButton> to reactivate or upgrade your subscription.
							</p>
						</div>
						<style>{`.subscription-error-modal .ant-modal-content { border-radius: 8px; }`}</style>
					</Modal>
					<FlowNavButtons
						primaryText="Create app"
						loading={loading}
					/>
				</Form>
			</FlowWrapper>
		</FlowLayout>
	)
}

export default React.memo(CreateAppByWelcomeMessage)
